#!/usr/bin/env python
"""Durable job queue worker. Completes each queued job exactly once."""
import sqlite3
import time

DB = "/var/lib/job-queue/jobs.sqlite3"
POLL = 0.5


def get_conn():
    conn = sqlite3.connect(DB, timeout=30, isolation_level=None)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=FULL")
    conn.execute("PRAGMA busy_timeout=30000")
    return conn


def process_one(conn):
    # Hold the write lock for the whole claim+complete so the job is either
    # left queued (and retried after a crash) or marked done -- never lost.
    conn.execute("BEGIN IMMEDIATE")
    try:
        row = conn.execute(
            "SELECT id, payload FROM jobs WHERE status='queued' ORDER BY id LIMIT 1"
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return False
        jid, payload = row
        conn.execute(
            "UPDATE jobs SET status='done', result=?, attempts=attempts+1 "
            "WHERE id=? AND status='queued'",
            ("processed:" + payload, jid),
        )
        conn.execute("COMMIT")
        return True
    except Exception:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        raise


def main():
    conn = get_conn()
    while True:
        try:
            if not process_one(conn):
                time.sleep(POLL)
        except sqlite3.OperationalError:
            # DB locked by another writer; back off briefly.
            time.sleep(0.1)
        except Exception:
            try:
                conn.close()
            except Exception:
                pass
            time.sleep(1)
            conn = get_conn()


if __name__ == "__main__":
    main()

